-- APPLIED on staging 2026-10-01 (verbatim). Restore list built from legacy packiot40 runtime rows
-- (exact line-name + runtime range match; chunked extract, counts verified = legacy counts).
-- 2026-10-01 (user: "check if it ever drains ... fix ... hardproof only"): CPACK + twin PO runtime rows
-- flagged but OUT of the 1-month compute window never drain (stranded). 333 per tenant are holes vs the
-- legacy oracle (NULL or < 0.98 x legacy net; legacy itself undercounts 2-9 pct, so higher staging is kept):
-- restore gross/net/running/available from legacy (exact line + range match). Then clear the stranded
-- runtime flags and re-sum the stranded headers with the engine's own recalcSQL (restricted by id).
SET statement_timeout = '600s';
SET lock_timeout = '20s';
BEGIN;
CREATE TEMP TABLE fix(id bigint, g double precision, n double precision, run double precision, av double precision) ON COMMIT DROP;
CREATE TABLE IF NOT EXISTS ops._bkp_po_runtime_legacy_restore_20261001 AS SELECT r.*, now() AS bkp_at FROM gold.production_orders_runtime r WHERE false;
SELECT 'restore_before', count(*), round(sum(r.net_production)::numeric), round(sum(f.n)::numeric) FROM gold.production_orders_runtime r JOIN fix f ON f.id = r.id_production_order_runtime;
UPDATE gold.production_orders_runtime r SET gross_production = f.g, net_production = f.n,
       running_time = COALESCE(round(f.run)::int, r.running_time), available_time = COALESCE(round(f.av)::int, r.available_time),
       last_update = now()
  FROM fix f WHERE r.id_production_order_runtime = f.id;
-- stranded runtime flags: closed rows entirely before the window can never be recomputed
CREATE TEMP TABLE rt_stranded ON COMMIT DROP AS SELECT id_production_order_runtime AS id, id_production_order FROM gold.production_orders_runtime
 WHERE recalc_needed AND upper(runtime_timerange) < now() - interval '1 month';
UPDATE gold.production_orders_runtime SET recalc_needed = false WHERE id_production_order_runtime IN (SELECT id FROM rt_stranded);
-- stranded headers: finished POs entirely before the recalc window
CREATE TEMP TABLE hdr_target ON COMMIT DROP AS SELECT id_production_order FROM core.production_orders
 WHERE recalc_needed AND status IN (3, 4) AND COALESCE(ts_end, ts_start) < now() - interval '1 month';
CREATE TABLE IF NOT EXISTS ops._bkp_po_hdr_stranded_20261001 AS SELECT p.*, now() AS bkp_at FROM core.production_orders p WHERE false;
SELECT 'stranded', (SELECT count(*) FROM rt_stranded), (SELECT count(*) FROM hdr_target);

	WITH eligible AS (
	    SELECT e.id_production_order
	      FROM core.production_orders e
	     -- A PO that STARTED before the window but ENDED inside it (a long run, or a
	     -- NULL ts_start the replicator never filled) is still a live header: prod's
	     -- ts_start-only test left it with whatever sum it had while running (2026-09-29).
	     WHERE e.id_production_order IN (SELECT id_production_order FROM hdr_target)
	), sums AS (
	    SELECT ca.id_production_order,
	           sum(ca.gross_production)  AS gross,
	           sum(ca.net_production)    AS net,
	           avg(ca.speed)             AS speed,
	           sum(ca.available_time)    AS avail,
	           sum(ca.available_time) + sum(ca.planned_downtime) AS total,
	           sum(ca.running_time)      AS run,
	           sum(ca.stopped_time)      AS stop,
	           sum(ca.planned_downtime)  AS planned
	      FROM gold.production_orders_runtime ca
	      JOIN eligible USING (id_production_order)
	     WHERE ca.runtime_timerange && tstzrange(now() - '6 months'::interval, now())
	     GROUP BY ca.id_production_order
	)
	UPDATE core.production_orders e SET
	       gross_production = COALESCE(s.gross, 0),
	       net_production   = COALESCE(s.net, 0),
	       -- #226 item 1b CONTRACT: writer repointed to canonical oee_q/oee_a/oee_p.
	       -- The legacy oee_quality/availability/performance cols (+ the old->new
	       -- dual-write trigger, gated on UPDATE OF those cols) are dropped in
	       -- migration 02; setting only the new cols makes that trigger inert
	       -- (never fires on a new-col-only UPDATE) — no clobber during rollout.
	       oee_q            = GREATEST(COALESCE(s.net / NULLIF(s.gross, 0), 0), 0),
	       speed            = COALESCE(s.speed, 0),
	       available_time   = COALESCE(s.avail, 0),
	       running_time     = COALESCE(s.run, 0),
	       stopped_time     = COALESCE(s.stop, 0),
	       planned_downtime = COALESCE(s.planned, 0),
	       -- ADR-0037 output-invariant clamp (#576 extended): PO OEE factors to [0,1].
	       oee = GREATEST(COALESCE(s.net / NULLIF(((s.total - s.planned) / 60.0) *
	             NULLIF(COALESCE(e.ideal_production_speed,
	                 (SELECT q.production_speed FROM core.equipments q
	                   WHERE q.id_equipment = e.id_equipment)), 0), 0), 0), 0),
	       oee_a = GREATEST(LEAST(COALESCE(s.run / NULLIF(s.avail, 0), 0), 1), 0),
	       oee_p  = GREATEST(COALESCE(
	             COALESCE(s.net / NULLIF(((s.total - s.planned) / 60.0) *
	                 NULLIF(COALESCE(e.ideal_production_speed,
	                     (SELECT q.production_speed FROM core.equipments q
	                       WHERE q.id_equipment = e.id_equipment)), 0), 0), 0)
	             / NULLIF(COALESCE(s.run / NULLIF(s.avail, 0), 0) *
	                      COALESCE(s.net / NULLIF(s.gross, 0), 0), 0), 0), 0),
	       recalc_needed = false,
	       last_update   = now()
	  FROM eligible el
	  LEFT JOIN sums s USING (id_production_order)
	 WHERE e.id_production_order = el.id_production_order;
SELECT 'restore_after', count(*), round(sum(r.net_production)::numeric) FROM gold.production_orders_runtime r JOIN fix f ON f.id = r.id_production_order_runtime;
SELECT 'hdr_after', count(*) FILTER (WHERE p.recalc_needed), round(sum(p.net_production)::numeric), round(sum(p.production_final)::numeric) FROM core.production_orders p JOIN hdr_target USING (id_production_order);
SELECT 'po_flags_left', count(*) FILTER (WHERE upper(runtime_timerange) < now() - interval '1 month'), count(*) FROM gold.production_orders_runtime WHERE recalc_needed;
SELECT 'hdr_flags_left', count(*) FROM core.production_orders WHERE recalc_needed;
COMMIT;
